import {span} from './nail-form.js';
// Immutable, nail-local surface recipes. Charms never enter this registry.
export const imprints=new Map();
export const clone=value=>JSON.parse(JSON.stringify(value));
export function defaultMirror(source,target){return source!==target&&source+target===9;}
export function stampOffset(u,v){const shift=x=>Math.abs(x-.5)<.14?0:Math.max(-.24,Math.min(.24,(x-.5)*.62));return {x:shift(u),y:shift(v)};}
export function isTransfer(a){return a?.tool==='stamp';}
export function hasBase(actions){return actions.some(a=>['brush','fan'].includes(a.tool)||(isTransfer(a)&&a.includeBase&&hasBase(imprints.get(a.imprintId)?.actions||[])));}
export function validTransfer(a){return !!a&&isTransfer(a)&&typeof a.imprintId==='string'&&imprints.has(a.imprintId)&&typeof a.mirror==='boolean'&&typeof a.includeBase==='boolean'&&Number.isFinite(a.aspect)&&a.aspect>.2&&a.aspect<5&&[a.offset?.x,a.offset?.y].every(v=>Number.isFinite(v)&&Math.abs(v)<=.24)&&(a.span===undefined||(Number.isFinite(a.span)&&a.span>=1&&a.span<=2.65))&&Number.isFinite(a.softness)&&a.softness>=0&&a.softness<=.5;}
export function makeTransfer(imprint,target,dimensions,u=.5,v=.5,flip=false,wet=false){return {tool:'stamp',span:target.span||1,surface:target.form?clone(target.form):undefined,imprintId:imprint.id,mirror:defaultMirror(imprint.sourceId,target.id)!==flip,offset:stampOffset(u,v),includeBase:!(target.basePresent??hasBase(target.actions)),aspect:dimensions[0]/dimensions[1],softness:wet?.35:0,material:imprint.actions.findLast(a=>a.material)?.material||'cream',points:[]};}
export function captureRecipe(sourceId,dimensions,actions,form){const recipe={id:`imprint-${Date.now()}-${Math.random().toString(36).slice(2,9)}`,sourceId,span:span(form),aspect:dimensions[0]/dimensions[1],actions:clone(actions)};imprints.set(recipe.id,recipe);return recipe;}
// Ordered references form a DAG: a newly captured nail may contain earlier transfers.
export function restoreImprints(data,validAction){imprints.clear();if(!Array.isArray(data))return;for(const r of data){if(!r||typeof r.id!=='string'||r.id.length>100||imprints.has(r.id)||!Number.isInteger(r.sourceId)||r.sourceId<0||r.sourceId>9||!Number.isFinite(r.aspect)||r.aspect<=.2||r.aspect>=5||(r.span!==undefined&&(!Number.isFinite(r.span)||r.span<1||r.span>2.65))||!Array.isArray(r.actions)||r.actions.length>20000||!r.actions.every(a=>validAction(a)))continue;imprints.set(r.id,clone(r));}}
export function savedImprints(nails,loadedId){const keep=new Set(),pending=[];for(const actions of nails)for(const a of actions)if(isTransfer(a))pending.push(a.imprintId);if(loadedId)pending.push(loadedId);while(pending.length){const id=pending.pop();if(keep.has(id))continue;const recipe=imprints.get(id);if(!recipe)continue;keep.add(id);for(const a of recipe.actions)if(isTransfer(a))pending.push(a.imprintId);}return [...imprints.values()].filter(r=>keep.has(r.id));}
